/**
 * Form indexes of the Russian adapter: a written form → the readings a source gives it. The same design as the Greek and Hebrew
 * stores (src/adapters/greek/index-store.ts), with a more compact row, because the Russian tables are larger (every noun in twelve
 * cells, every verb with its participles).
 *
 * Indexes, all GENERATED by scripts/ru-build-index.mts from the Wiktionary extract of kaikki.org (CC BY-SA 4.0):
 *   ru-core            the closed classes and the commonest lemmas with every form of theirs, compiled into the analyser
 *                      (russian/generated/core.ts) so that a host with no assets still reads ordinary prose.
 *   kaikki-ru-tables   every inflection-table row and every form-of page of the extract, SHARDED (public/lexicon/ru/standard/),
 *                      loaded on demand by the shared loader (russian/shards.ts) and installed beside the core.
 *
 * Keys are `ruKey(form)` (text.ts): lower case, no stress marks, ё kept. `yo` maps an е-spelling to the keys that have ё, so a text
 * printed without ё reaches them. A row never invents anything: lemma, tags and stress are the source's, verbatim.
 */
import { unpackStress, yoFold, type PackedStress } from './text';

/**
 * One lexeme:
 *   head      the headword as the source writes it, WITH its stress mark ("кни́га", "прочита́ть", "идти́")
 *   gloss     the source's first gloss, shortened ("book")
 *   pos       UPOS (NOUN, PROPN, VERB, ADJ, ADV, PRON, DET, ADP, CONJ, SCONJ, PART, NUM, INTJ)
 *   lex       the features of the lexeme itself, as "Key=Value|Key=Value" (sorted by key): Gender and Animacy of a noun,
 *             Aspect of a verb (Imp, Perf, or "Imp,Perf" for a biaspectual verb), Reflex=Yes, Subcat=Tran|Intr; "" when none
 *   count     how often the lemma (with this part of speech) occurs in the priors corpus (0 = not seen there); orders readings
 *   partners  for a verb, the headword(s) of the other aspect the source names in its head line, with stress
 *             ("чита́ть" → ["прочита́ть", "почита́ть", "проче́сть"]); absent when the source names none
 */
export type RuLemmaRow = [head: string, gloss: string, pos: string, lex: string, count: number, partners?: string[]];

/** One reading of a form: [index into `lemmaIds`, index into `codes`, the stressed vowel(s) of this form (text.ts PackedStress)]. */
export type RuFormRow = [lemma: number, code: number, stress?: PackedStress];

export interface RussianFormIndex {
  schema: 1;
  id: 'ru-core' | 'kaikki-ru-tables' | string;
  /** A SHARD of a larger index: the prefix of the letters its keys share (text.ts `ruShardLetters`); shards of one id sit side by side. */
  shard?: string;
  source: { label: string; licence: string; url: string; lastModified?: string; retrieved?: string; sha256?: string; note?: string };
  built: string;
  /**
   * The tag bundles rows refer to: the source's own labels for the form, verbatim, sorted and joined with "|"
   * ("accusative|singular", "first-person|present|singular", "feminine|past|singular", "active|participle|present|…").
   * russian/tags.ts turns a bundle into features; nothing is interpreted at build time.
   */
  codes: string[];
  /** The lemma ids rows refer to: "<key of the headword>|<POS>", with "|2", "|3" … for a further entry of the same word and part of speech (за́мок, замо́к). */
  lemmaIds: string[];
  lemmas: Record<string, RuLemmaRow>;
  forms: Record<string, RuFormRow[]>;
  /** е-spelling → the keys of this index that differ from it only by ё (only where at least one key has ё). */
  yo: Record<string, string[]>;
  stats?: Record<string, number>;
}

export interface RuIndexHit {
  index: RussianFormIndex;
  /** The key the reading is filed under (differs from the looked-up key when `viaYo`). */
  key: string;
  lemmaId: string;
  lemma: RuLemmaRow;
  /** The source's tag bundle for the form. */
  code: string;
  /** Positions of the stressed vowels in `key`; empty when the source marks none. */
  stress: number[];
  /** True when the text wrote е and the form has ё: the ё is restored, and the reading says so. */
  viaYo: boolean;
}

const INSTALLED = new Map<string, RussianFormIndex>();
const storeKey = (id: string, shard?: string): string => (shard ? `${id}#${shard}` : id);

/** Installs an index, or one shard of one (keyed by id and shard); re-installing replaces. */
export function installRussianIndex(idx: RussianFormIndex): void { INSTALLED.set(storeKey(idx.id, idx.shard), idx); }
export function uninstallRussianIndex(id: string, shard?: string): boolean { return INSTALLED.delete(storeKey(id, shard)); }
export function installedRussianIndexes(): RussianFormIndex[] { return [...INSTALLED.values()]; }
/** Forgets every installed index (or shard) for which `keep(id, shard)` is not true. */
export function resetRussianIndexes(keep?: (id: string, shard?: string) => boolean): void {
  for (const [k, idx] of [...INSTALLED.entries()]) if (!keep?.(idx.id, idx.shard)) INSTALLED.delete(k);
}

function rowsOf(index: RussianFormIndex, key: string, viaYo: boolean, out: RuIndexHit[], seen: Set<string>): void {
  for (const row of index.forms[key] ?? []) {
    const lemmaId = index.lemmaIds[row[0]];
    const lemma = index.lemmas[lemmaId];
    const code = index.codes[row[1]];
    if (!lemma || code === undefined) continue;
    // the core and a shard may both hold the same reading: it is listed once
    const sig = `${key}\t${lemmaId}\t${code}\t${row[2] ?? ''}`;
    if (seen.has(sig)) continue;
    seen.add(sig);
    out.push({ index, key, lemmaId, lemma, code, stress: unpackStress(row[2]), viaYo });
  }
}

/**
 * The readings of a key across the installed indexes: the form as written first, then, when the key has no ё, the forms that
 * differ from it only by ё (marked `viaYo`). Both lists are always given: "все" is a form of весь and may be всё printed without
 * its dots, and only the sentence can say which. Order within each list: the lemma's count, highest first.
 */
export function lookupRussianForm(key: string): RuIndexHit[] {
  const direct: RuIndexHit[] = [];
  const restored: RuIndexHit[] = [];
  const seen = new Set<string>();
  for (const index of INSTALLED.values()) rowsOf(index, key, false, direct, seen);
  if (!key.includes('ё')) {
    const folded = yoFold(key);
    for (const index of INSTALLED.values()) for (const k of index.yo[folded] ?? []) if (k !== key) rowsOf(index, k, true, restored, seen);
  }
  const byCount = (a: RuIndexHit, b: RuIndexHit): number => b.lemma[4] - a.lemma[4];
  return [...direct.sort(byCount), ...restored.sort(byCount)];
}

/** The lemma row of an id, from any installed index (or the one given). */
export function lookupRussianLemma(lemmaId: string, index?: RussianFormIndex): RuLemmaRow | undefined {
  if (index) return index.lemmas[lemmaId];
  for (const idx of INSTALLED.values()) { const r = idx.lemmas[lemmaId]; if (r) return r; }
  return undefined;
}

/** The headword of a lemma id without its stress mark and suffixes: "книга|NOUN" → "книга", "замок|NOUN|2" → "замок". */
export const lemmaOfId = (lemmaId: string): string => lemmaId.split('|')[0];
